import React, { useEffect, useState } from "react";
import Navbar from "../Components/Navbar";
import Footer from "../Components/Footer";
import { useNavigate } from "react-router-dom";
import API_BASE_URL from "../config";
import "../App.css";

const MyListings = () => {
  const navigate = useNavigate();
  const userId = sessionStorage.getItem("userId");
  const [listings, setListings] = useState([]);

  useEffect(() => {
    if (userId) {
      fetch(`${API_BASE_URL}/api/listings/user/${userId}`)
        .then((res) => res.json())
        .then((data) => setListings(data))
        .catch((err) => console.error("Error fetching listings:", err));
    }
  }, [userId]);

  return (
    <div className="dashboard-wrapper">
      <Navbar />
      <main className="dashboard-main">
        <h2 style={{ textAlign: "center", marginBottom: "32px" }}>My Listings</h2>

        <div className="item-grid">
          {listings.length > 0 ? (
            listings.map((item) => (
              <div className="item-card" key={item.id}>
                <div className="image-placeholder">
                  {item.image ? <img src={item.image} alt={item.title} /> : <span>No Image</span>}
                </div>
                <h4>{item.title}</h4>
                <p>{item.description}</p>
                <p><strong>Condition:</strong> {item.condition}</p>
                <p><strong>Price:</strong> ${parseFloat(item.price).toFixed(2)}</p>
                <p><strong>Status:</strong> {item.sold ? "SOLD" : "Available"}</p>
                <div className="item-actions">
                  <button
                    className="edit-btn"
                    onClick={() => navigate(`/edit-listing/${item.id}`)}
                  >
                    Edit
                  </button>
                </div>
              </div>
            ))
          ) : (
            <p style={{ textAlign: "center" }}>You haven’t listed anything yet.</p>
          )}
        </div>
      </main>
      <Footer />
    </div>
  );
};

export default MyListings;
